// Package hostops holds the host operations' payloads in the FlatBuffers aligned binary layout (the SDK's
// schemas/runtime/HostOps.fbs, generated by generate.mjs) and reads / writes them as plain field maps.
//
// A hostcall is an SDS $PIV invocation in the module -> host direction: its "params" / "result" frames are one
// record each, a list port is a run of records at a fixed stride, and unbounded bytes travel on raw ports beside them.
// Field maps are keyed by the schema's field names (SCHEMA, BEFORE_MS, ...). A field whose presence bit is clear
// is absent from the map; strings that do not fit their record are refused, never truncated.
package hostops

import (
	"fmt"
	"reflect"
	"sort"
	"strings"
	"sync"
)

// RecordType is one aligned record: its size, alignment and view constructor.
type RecordType struct {
	Name  string
	Size  int
	Align int
	View  func(buffer []byte, offset int) any
}

// Operation is one host operation's frames (empty Params / Result: none) and the capability it needs.
type Operation struct {
	Params, Result, Capability string
	RawIn, RawOut              []string
	ListsIn, ListsOut          map[string]string
}

// Record returns the named record type.
func Record(name string) (RecordType, error) {
	t, ok := Records[name]
	if !ok {
		return RecordType{}, fmt.Errorf("hostops: %q is not a HostOps record", name)
	}
	return t, nil
}

// field describes one schema field of a view type, found from its accessor methods.
type field struct {
	name     string
	vector   bool
	presence bool
}

var fieldCache sync.Map // reflect.Type -> []field

func fieldsOf(viewType reflect.Type) []field {
	if cached, ok := fieldCache.Load(viewType); ok {
		return cached.([]field)
	}
	methods := map[string]reflect.Method{}
	for i := 0; i < viewType.NumMethod(); i++ {
		m := viewType.Method(i)
		methods[m.Name] = m
	}
	var out []field
	for name, m := range methods {
		if strings.HasPrefix(name, "Has") || strings.HasPrefix(name, "Mutate") || strings.HasSuffix(name, "Length") {
			continue
		}
		// receiver + (j int) for a vector element, receiver alone for a scalar / string / nested record
		_, hasLength := methods[name+"Length"]
		switch {
		case m.Type.NumIn() == 2 && hasLength:
			_, presence := methods["Has"+name]
			out = append(out, field{name: name, vector: true, presence: presence})
		case m.Type.NumIn() == 1 && m.Type.NumOut() == 1:
			_, presence := methods["Has"+name]
			out = append(out, field{name: name, presence: presence})
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].name < out[j].name })
	fieldCache.Store(viewType, out)
	return out
}

// Fields lists a record's schema field names (sorted).
func Fields(name string) []string {
	t, ok := Records[name]
	if !ok {
		return nil
	}
	var names []string
	for _, f := range fieldsOf(reflect.TypeOf(t.View(make([]byte, t.Size), 0))) {
		names = append(names, f.name)
	}
	return names
}

func isRecordView(t reflect.Type) bool {
	if t.Kind() != reflect.Struct {
		return false
	}
	f, ok := t.FieldByName("Buffer")
	return ok && f.Type == reflect.TypeOf([]byte(nil))
}

// Read reads one record of type name from bytes (exactly its size).
func Read(name string, bytes []byte) (map[string]any, error) {
	t, err := Record(name)
	if err != nil {
		return nil, err
	}
	if len(bytes) != t.Size {
		return nil, fmt.Errorf("hostops: %s is %d bytes, the frame %d", name, t.Size, len(bytes))
	}
	return readView(reflect.ValueOf(t.View(bytes, 0))), nil
}

// ReadList reads a run of records of type name (a list port).
func ReadList(name string, bytes []byte) ([]map[string]any, error) {
	t, err := Record(name)
	if err != nil {
		return nil, err
	}
	if t.Size == 0 || len(bytes)%t.Size != 0 {
		return nil, fmt.Errorf("hostops: list of %s is %d bytes, not a whole number of %d-byte records", name, len(bytes), t.Size)
	}
	out := make([]map[string]any, 0, len(bytes)/t.Size)
	for offset := 0; offset < len(bytes); offset += t.Size {
		out = append(out, readView(reflect.ValueOf(t.View(bytes, offset))))
	}
	return out, nil
}

func readView(view reflect.Value) map[string]any {
	out := map[string]any{}
	for _, f := range fieldsOf(view.Type()) {
		if f.presence && !view.MethodByName("Has" + f.name).Call(nil)[0].Bool() {
			continue
		}
		if f.vector {
			n := int(view.MethodByName(f.name + "Length").Call(nil)[0].Int())
			at := view.MethodByName(f.name)
			values := make([]any, 0, n)
			for j := 0; j < n; j++ {
				values = append(values, at.Call([]reflect.Value{reflect.ValueOf(j)})[0].Interface())
			}
			out[f.name] = values
			continue
		}
		value := view.MethodByName(f.name).Call(nil)[0]
		if isRecordView(value.Type()) {
			out[f.name] = readView(value)
			continue
		}
		out[f.name] = value.Interface()
	}
	return out
}

// Write builds one record of type name from field values (unknown fields and strings that do not fit are errors).
func Write(name string, values map[string]any) ([]byte, error) {
	t, err := Record(name)
	if err != nil {
		return nil, err
	}
	bytes := make([]byte, t.Size)
	if err := writeView(reflect.ValueOf(t.View(bytes, 0)), values, name); err != nil {
		return nil, err
	}
	return bytes, nil
}

// WriteList builds a run of records of type name (a list port).
func WriteList(name string, list []map[string]any) ([]byte, error) {
	t, err := Record(name)
	if err != nil {
		return nil, err
	}
	bytes := make([]byte, t.Size*len(list))
	for i, values := range list {
		if err := writeView(reflect.ValueOf(t.View(bytes, i*t.Size)), values, fmt.Sprintf("%s[%d]", name, i)); err != nil {
			return nil, err
		}
	}
	return bytes, nil
}

func writeView(view reflect.Value, values map[string]any, where string) error {
	known := map[string]field{}
	for _, f := range fieldsOf(view.Type()) {
		known[f.name] = f
	}
	for key, value := range values {
		if value == nil {
			continue
		}
		f, ok := known[key]
		if !ok {
			return fmt.Errorf("hostops: %s has no field %s", where, key)
		}
		setPresence := func() {
			if f.presence {
				view.MethodByName("MutateHas" + f.name).Call([]reflect.Value{reflect.ValueOf(true)})
			}
		}
		if f.vector {
			items := reflect.ValueOf(value)
			if items.Kind() != reflect.Slice {
				return fmt.Errorf("hostops: %s.%s takes a list", where, key)
			}
			view.MethodByName("Mutate" + f.name + "Length").Call([]reflect.Value{reflect.ValueOf(items.Len())})
			if got := int(view.MethodByName(f.name + "Length").Call(nil)[0].Int()); got != items.Len() {
				return fmt.Errorf("hostops: %s.%s: %d items exceed the record's bound", where, key, items.Len())
			}
			mutate := view.MethodByName("Mutate" + f.name)
			elem := mutate.Type().In(1)
			for j := 0; j < items.Len(); j++ {
				v, err := convert(items.Index(j).Interface(), elem)
				if err != nil {
					return fmt.Errorf("hostops: %s.%s[%d]: %w", where, key, j, err)
				}
				mutate.Call([]reflect.Value{reflect.ValueOf(j), v})
			}
			setPresence()
			continue
		}
		get := view.MethodByName(f.name)
		if isRecordView(get.Type().Out(0)) {
			nested, ok := value.(map[string]any)
			if !ok {
				return fmt.Errorf("hostops: %s.%s takes a record", where, key)
			}
			if err := writeView(get.Call(nil)[0], nested, where+"."+key); err != nil {
				return err
			}
			setPresence()
			continue
		}
		mutate := view.MethodByName("Mutate" + f.name)
		v, err := convert(value, mutate.Type().In(0))
		if err != nil {
			return fmt.Errorf("hostops: %s.%s: %w", where, key, err)
		}
		mutate.Call([]reflect.Value{v})
		setPresence()
		if s, isString := value.(string); isString && get.Call(nil)[0].String() != s {
			return fmt.Errorf("hostops: %s.%s: %d bytes exceed the record's string (refused, not truncated)", where, key, len(s))
		}
	}
	return nil
}

func convert(value any, to reflect.Type) (reflect.Value, error) {
	v := reflect.ValueOf(value)
	switch to.Kind() {
	case reflect.String:
		if v.Kind() != reflect.String {
			return reflect.Value{}, fmt.Errorf("takes text, got %T", value)
		}
		return v.Convert(to), nil
	case reflect.Bool:
		if v.Kind() != reflect.Bool {
			return reflect.Value{}, fmt.Errorf("takes a bool, got %T", value)
		}
		return v, nil
	case reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Float32, reflect.Float64:
		switch v.Kind() {
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64, reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Float32, reflect.Float64:
			out := v.Convert(to)
			// refuse a value the field cannot hold (a negative into an unsigned field, an overflow)
			back := out.Convert(v.Type())
			if !reflect.DeepEqual(back.Interface(), v.Interface()) && to.Kind() != reflect.Float32 && to.Kind() != reflect.Float64 {
				return reflect.Value{}, fmt.Errorf("%v does not fit %s", value, to)
			}
			return out, nil
		case reflect.Bool:
			if v.Bool() {
				return reflect.ValueOf(1).Convert(to), nil
			}
			return reflect.ValueOf(0).Convert(to), nil
		}
		return reflect.Value{}, fmt.Errorf("takes a number, got %T", value)
	}
	return reflect.Value{}, fmt.Errorf("unsupported field type %s", to)
}
